/**
 * FolderItem Component - Displays a single folder
 * 
 * Responsibilities:
 * - Show folder name
 * - Handle folder click (navigate into)
 * - Show folder icon
 * 
 * Import rules:
 * - Can import: hooks (if needed)
 * - Can import: other components
 * - Should NOT import: services, pages
 */

import React from 'react';

const FolderItem = ({ folder, onNavigate }) => {
  return (
    <div className="folder-item" onClick={() => onNavigate(folder.id, folder.name)}>
      <div className="folder-icon">📁</div>
      <div className="folder-name">{folder.name}</div>
    </div>
  );
};

export default FolderItem;
